  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}

.kpi {
  padding: 14px;
}

.kpi span,
.panel-head span {
  display: block;
  color: #64748b;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
