const colors = ["#2563eb", "#14b8a6", "#f59e0b", "#dc2626", "#7c3aed", "#16a34a"];
function money(value) {
  return Number(value || 0).toFixed(2);
}
function num(value) {
  return Number(value || 0);
}
function esc(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}
function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.innerText = value;
}
function todayIso() {
  return new Date().toISOString().slice(0, 10);
}
function addDays(days) {
  const d = new Date();
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}
function monthStart() {
  const d = new Date();
  d.setDate(1);
  return d.toISOString().slice(0, 10);
}
function applyPeriod(from, to) {
  document.getElementById("dateFrom").value = from;
  document.getElementById("dateTo").value = to;
  appsmith.updateModel({
    dateFrom: from,
    dateTo: to
  });
  appsmith.triggerEvent("onPeriodChange");
}
function renderHourly(rows = []) {
  const root = document.getElementById("hourlyChart");
  if (!root) return;
  const byHour = {};
  rows.forEach(row => {
    byHour[Number(row.hourValue)] = num(row.salesAmount);
  });
  const values = Array.from({
    length: 24
  }, (_, hour) => ({
    hour,
    amount: byHour[hour] || 0
  }));
  const max = Math.max(...values.map(x => x.amount), 1);
  const peak = values.reduce((best, row) => row.amount > best.amount ? row : best, values[0]);
  setText("peakHour", peak.amount > 0 ? `${String(peak.hour).padStart(2, "0")}:00 / ${money(peak.amount)}` : "--");
  root.innerHTML = values.map(row => {
    const h = Math.max(3, Math.round(row.amount / max * 190));
    return `
      <div class="hour" title="${row.hour}:00 - ${money(row.amount)}">
        <div class="bar" style="height:${h}px"></div>
        <label>${row.hour}</label>
      </div>
    `;
  }).join("");
}
function renderTrend(rows = []) {
  const svg = document.getElementById("trendChart");
  if (!svg) return;
  if (!rows.length) {
    svg.innerHTML = `<text x="310" y="110" text-anchor="middle" fill="#64748b">No trend data</text>`;
    return;
  }
  const width = 620;
  const height = 220;
  const pad = 24;
  const max = Math.max(...rows.map(r => num(r.salesAmount)), 1);
  const points = rows.map((row, i) => {
    const x = pad + i * ((width - pad * 2) / Math.max(rows.length - 1, 1));
    const y = height - pad - num(row.salesAmount) / max * (height - pad * 2);
    return {
      x,
      y,
      value: num(row.salesAmount),
      label: row.salesDate
    };
  });
  const line = points.map(p => `${p.x},${p.y}`).join(" ");
  const area = `${pad},${height - pad} ${line} ${width - pad},${height - pad}`;
  svg.innerHTML = `
    <line class="gridline" x1="${pad}" y1="${height - pad}" x2="${width - pad}" y2="${height - pad}"></line>
    <line class="gridline" x1="${pad}" y1="${pad}" x2="${width - pad}" y2="${pad}"></line>
    <polygon class="area" points="${area}"></polygon>
    <polyline class="line" points="${line}"></polyline>
    ${points.map(p => `<circle class="point" cx="${p.x}" cy="${p.y}" r="5"><title>${esc(p.label)}: ${money(p.value)}</title></circle>`).join("")}
  `;
}
function renderAlerts(rows = []) {
  const root = document.getElementById("alerts");
  if (!root) return;
  if (!rows.length) {
    root.innerHTML = `<div class="empty">No sales alerts for this period.</div>`;
    return;
  }
  root.innerHTML = rows.map(row => `
    <div class="alert ${esc(row.severity || "INFO")}">
      <strong>${esc(row.title)}</strong>
      <span>${esc(row.detail)}</span>
    </div>
  `).join("");
}
function renderMix(rows = []) {
  const donut = document.getElementById("mixDonut");
  const legend = document.getElementById("mixLegend");
  if (!donut || !legend) return;
  const total = rows.reduce((s, r) => s + num(r.amountValue), 0);
  if (!rows.length || total <= 0) {
    donut.style.background = "#e5e7eb";
    legend.innerHTML = `<div class="empty">No payment data</div>`;
    return;
  }
  let start = 0;
  const parts = rows.map((row, i) => {
    const pct = num(row.amountValue) / total * 100;
    const end = start + pct;
    const segment = `${colors[i % colors.length]} ${start}% ${end}%`;
    start = end;
    return segment;
  });
  donut.style.background = `conic-gradient(${parts.join(",")})`;
  legend.innerHTML = rows.map((row, i) => `
    <div class="legend-row">
      <div class="swatch" style="background:${colors[i % colors.length]}"></div>
      <div>${esc(row.mixLabel)}</div>
      <strong>${money(row.amountValue)}</strong>
    </div>
  `).join("");
}
function renderTopProducts(rows = []) {
  const root = document.getElementById("topProducts");
  if (!root) return;
  if (!rows.length) {
    root.innerHTML = `<div class="empty">No product sales in this period.</div>`;
    return;
  }
  const max = Math.max(...rows.map(r => num(r.salesAmount)), 1);
  root.innerHTML = rows.map(row => {
    const width = Math.max(4, Math.round(num(row.salesAmount) / max * 100));
    return `
      <div class="product-row">
        <div>
          <div class="product-name">${esc(row.productName || "Product")}</div>
          <div class="product-code">${esc(row.productCode || "")} / Qty ${num(row.quantity).toFixed(2)}</div>
        </div>
        <div class="product-bar"><div style="width:${width}%"></div></div>
        <div class="product-amount">${money(row.salesAmount)}</div>
      </div>
    `;
  }).join("");
}
function wireControls(model = {}) {
  const from = document.getElementById("dateFrom");
  const to = document.getElementById("dateTo");
  from.value = model.dateFrom || todayIso();
  to.value = model.dateTo || todayIso();
  document.getElementById("applyBtn").onclick = () => applyPeriod(from.value, to.value);
  document.getElementById("todayBtn").onclick = () => applyPeriod(todayIso(), todayIso());
  document.getElementById("weekBtn").onclick = () => applyPeriod(addDays(-6), todayIso());
  document.getElementById("monthBtn").onclick = () => applyPeriod(monthStart(), todayIso());
}
function render(model = {}) {
  const kpis = model.kpis || {};
  setText("totalSales", `${money(kpis.totalSales)} EUR`);
  setText("documentCount", num(kpis.documentCount));
  setText("averageDocument", `${money(kpis.averageDocument)} EUR`);
  setText("fiscalIssues", num(kpis.fiscalIssues));
  setText("generatedAt", "Updated: " + (model.generatedAt || ""));
  wireControls(model);
  renderHourly(model.hourly || []);
  renderTrend(model.trend || []);
  renderAlerts(model.alerts || []);
  renderMix(model.mix || []);
  renderTopProducts(model.topProducts || []);
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

